pub struct Index {
    pub titles: Vec<String>,
    pub docs: Vec<String>,
    pub vecs: Vec<Vec<f32>>,
}

impl Index {
    pub fn new() -> Self {
        Index { titles: Vec::new(), docs: Vec::new(), vecs: Vec::new() }
    }

    pub fn add(&self, title: &str, text: &str) {
        self.vecs.push(embed(text));
        self.docs.push(text.to_string());
