        self.vecs.push(embed(text, &self.idf));
        self.docs.push(text.to_string());
        self.titles.push(title.to_string());
    }

    pub fn fit(&mut self) {
        self.idf = idf_table(&self.docs);
        let vecs: Vec<Vec<f32>> = self.docs.iter().map(|d| embed(d, &self.idf)).collect();
